    def m4050(self):
        # 目前所有机型的4050都要取消
        self.gcode.respond_info("M4050: Pre-print model check is disabled, skipping detection")
        return  
        if not self.ai_configs[AIErrorType.FOREIGN]["enabled"]:
            self.gcode.respond_info("M4050: Pre-print model check is disabled, skipping detection")
            return        
        toolhead = self.printer.lookup_object('toolhead')
        gcode = self.printer.lookup_object('gcode')
        reactor = self.printer.get_reactor()
        self.gcode.respond_info("M4050: Moving to inspection point...")
        gcode.run_script_from_command("G28 X Y")
        gcode.run_script_from_command("G1 X125 Y403 F12000")
        
        toolhead.wait_moves()

        # --- 步骤 2: 原地阻塞轮询 (不阻塞 Reactor) ---
        url = "http://localhost:9010/detection_res#/"
        max_wait_time = 20.0
        start_time = reactor.monotonic()
        self.gcode.respond_info("M4050: Detection started...")

        found_error = False
        while reactor.monotonic() - start_time < max_wait_time:
            try:
                # 使用非阻塞方式让出 CPU 权限，允许 Klipper 处理其他事务（温度、通讯）这里 pause 100ms 相当于让渡使用权
                reactor.pause(reactor.monotonic() + 0.8)

                response = requests.get(url, timeout=0.2) # 降低超时，防止卡顿
                if response.status_code == 200:
                    data = response.json()
                    status = data.get("foreign_count", 0)

                    if status > 0:
                        self.gcode.respond_info("M4050: Foreign object detected!")
                        found_error = True
                        if self.ai_configs[AIErrorType.FOREIGN]['count'] > 0:
                            return
                        self.ai_error_type = AIErrorType.FOREIGN
                        self.ai_configs[AIErrorType.FOREIGN]['count'] += 1
                        break
            except Exception as e:
                pass

        if found_error:
            gcode.run_script_from_command("PAUSE")
        else:
            self.gcode.respond_info("M4050: No foreign objects found. Continuing...")

        self.gcode.respond_info("M4050: Foreign object detection over")


    def _foreign_notice(self, text):
        saved = self.printer.lookup_object('save_variables')
        cmd = self.gcode.create_gcode_command('SAVE_VARIABLE', 'foreign preflight',
            {'VARIABLE': 'qdc_ai_error_code', 'VALUE': repr(text)})
        saved.cmd_SAVE_VARIABLE(cmd)

    def _forget_ai_alarm(self):
        # The alarm text the screen reads (qdc_ai_error_code, "... status=1") stayed stored after a print, and the screen showed its window
        # again at the start of the next one (25.11.2026). QIDI's own pre-print check cleared it before it started. Returns what was cleared.
        stored = str(getattr(self.save_variables, 'qdc_ai_error_code', '') or '')
        if 'status=1' not in stored:
            return None
        self._foreign_notice('')
        return stored.strip()

    def _foreign_clear_notice(self, context):
        text = context.get('notice')
        if text and getattr(self.save_variables, 'qdc_ai_error_code', None) == text:
            try:
                self._foreign_notice('')
            except Exception:
                logging.warning('M4050: could not clear own notice', exc_info=True)

    def foreign_preflight_command(self, command):
        # This is a stationary pause BEFORE any file G-code, not a mid-print
        # pause. The stock macros would retract, park or restore a position.
        context = self._foreign_preflight
        if context is None:
            return False
        sd = context['sd']
        if sd.current_file is not context['file']:
            self._foreign_preflight = None
            return False
        pause = self.printer.lookup_object('pause_resume')
        if command in ('CANCEL_PRINT', 'BASE_CANCEL_PRINT', 'SDCARD_RESET_FILE'):
            sd.do_cancel()
            pause.is_paused = pause.sd_paused = pause.pause_command_sent = False
            context['phase'] = 'cancelled'
            self._foreign_clear_notice(context)
            self._foreign_preflight = None
        elif command in ('RESUME', 'BASE_RESUME', 'RESUME_PRINT', 'M24'):
            # Continue is the owner's explicit override, never another check.
            context['phase'] = 'continue'
            self._foreign_clear_notice(context)
            if sd.work_timer is None:
                sd.do_resume()
            else:
                sd.must_pause_work = False
            pause.is_paused = pause.sd_paused = pause.pause_command_sent = False
            self._foreign_preflight = None
        elif command in ('PAUSE', 'BASE_PAUSE', 'M25', 'M9925'):
            context['phase'] = 'held'
            sd.must_pause_work = True
            pause.is_paused = pause.sd_paused = pause.pause_command_sent = True
        else:
            self.gcode.respond_info('PEI foreign object check: use Continue or Cancel for the waiting print.')
        return True

    def m4050(self):
        if not self.ai_configs[AIErrorType.FOREIGN]['enabled']:
            return
        sd = self.printer.lookup_object('virtual_sdcard')
        # The stock SD worker calls once per fresh file, before its first read.
        if sd.current_file is None or sd.file_position != 0 or sd.has_run_m4050:
            return
        context = {'sd': sd, 'file': sd.current_file, 'phase': 'checking', 'notice': None}
        self._foreign_preflight = context
        reactor = self.printer.get_reactor()
        base = 'http://127.0.0.1:9010'
        attempted_start = False

        def stamp(moment):
            return time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(moment))

        def light():
            # What the case light does when the AI looks at the plate (25.11.2026: nothing in the log said when it came on).
            try:
                value = self.printer.lookup_object('output_pin caselight').get_status(reactor.monotonic())['value']
                return 'on' if float(value) > 0 else 'off'
            except Exception:
                return 'unknown'

        def where():
            # Where the toolhead and the bed stand when the AI looks at the plate (the park position after a print is X260 Y260 Z50 from the
            # module park-rear-right; the audit of October found alarms on an empty plate at some bed heights only).
            try:
                status = self.printer.lookup_object('toolhead').get_status(reactor.monotonic())
                x, y, z = [float(v) for v in status['position'][:3]]
                return 'X%.1f Y%.1f Z%.1f, homed axes "%s"' % (x, y, z, status.get('homed_axes', ''))
            except Exception:
                return 'unknown'

        def save_frames(tag):
            # The pictures the AI looked at when it reported an object (25.11.2026: not one such picture existed, so nobody could say
            # whether the plate was empty). A few small files in a folder of the log directory; the oldest are removed.
            try:
                import base64, os
                folder = getattr(self, '_alarm_frames_dir', '/home/qidi/printer_data/logs/q2-alarm-frames')
                os.makedirs(folder, exist_ok=True)
                pictures = []
                for name, path in (('ai', '/history_frames?type=foreign'), ('now', '/capture')):
                    try:
                        reply = requests.get(base + path, timeout=0.5, allow_redirects=False)
                        data = reply.json() if reply.status_code == 200 else None
                    except Exception:
                        continue
                    for k, item in enumerate(data if isinstance(data, list) else [data]):
                        raw = item.get('image') if isinstance(item, dict) else item
                        if isinstance(raw, str) and raw:
                            pictures.append(('%s%d' % (name, k), raw))
                saved = []
                for name, raw in pictures:
                    target = '%s/%s_%s_%s.jpg' % (folder, time.strftime('%Y%m%d-%H%M%S', time.localtime(time.time())), tag, name)
                    with open(target, 'wb') as out:
                        out.write(base64.b64decode(raw))
                    saved.append(target)
                for stale in sorted(os.listdir(folder))[:-12]:
                    os.remove(os.path.join(folder, stale))
                if saved:
                    self.gcode.respond_info('PEI foreign object check: the pictures of the AI were saved: %s' % ', '.join(saved))
            except Exception:
                logging.warning('M4050: could not save the pictures of the AI', exc_info=True)

        try:
            # An AI alarm that is already stored when the print starts was not raised by this print (25.11.2026: the screen
            # showed the window of an earlier alarm through a whole print, with nothing in the console or the log).
            stored = str(getattr(self.save_variables, 'qdc_ai_error_code', '') or '')
            fields = dict(part.split('=', 1) for part in stored.replace("'", ' ').replace('"', ' ').split() if '=' in part)
            if float(fields.get('foreign', '0')) > 0:
                raised = ''
                if fields.get('time', '').isdigit():
                    raised = ', raised %s' % stamp(int(fields['time']))
                self.gcode.respond_info('PEI foreign object check: at the start of this print (%s) the AI alarm "%s" was already stored%s; this print did not raise it.' % (stamp(time.time()), stored.strip(), raised))
            gone = self._forget_ai_alarm()
            if gone:
                self.gcode.respond_info('PEI foreign object check: the stored AI alarm "%s" was cleared (%s), as the pre-print check of QIDI did before it started.' % (gone, stamp(time.time())))
        except Exception:
            logging.warning('M4050: could not read or clear the stored AI alarm', exc_info=True)

        def counters():
            response = requests.get(base + '/detection_res', timeout=0.2,
                                    allow_redirects=False)
            if response.status_code != 200:
                raise ValueError('AI result HTTP status')
            data = response.json()
            frame, foreign = data['frame_detect_pos_count'], data['foreign_count']
            if (type(frame) is not int or frame < 0
                    or type(foreign) not in (int, float) or not 0 <= foreign < float('inf')):
                raise ValueError('AI result counters')
            return frame, foreign

        def asked_again(call):
            # A service that was swapped out (25.11.2026, first print on the zram kernel) does not answer the first request within
            # 0.2 s. Only a missing answer is tried again (the pause lets Klipper work meanwhile); an answer that is wrong is not.
            for attempt in range(5):
                try:
                    return call()
                except OSError:
                    if attempt == 4:
                        raise
                    reactor.pause(reactor.monotonic() + 1.0)

        try:
            initial_frame, initial_foreign = asked_again(counters)
            attempted_start = True
            response = asked_again(lambda: requests.post(base + '/set_homing_state', json={'state': True},
                                                         timeout=0.2, allow_redirects=False))
            if response.status_code != 200:
                raise ValueError('AI start HTTP status')
            ack = response.json()
            if ack.get('status') != 'success' or ack.get('homing_state') is not True:
                raise ValueError('AI start not confirmed')
            # The endpoint controls the existing AI worker; no axis is homed.
            self.gcode.respond_info('PEI foreign object check: looking at the plate, without movement.')
            self.gcode.respond_info('PEI foreign object check: the case light is %s at %s.' % (light(), stamp(time.time())))
            self.gcode.respond_info('PEI foreign object check: the toolhead is at %s.' % where())
            started = reactor.monotonic()
            deadline = started + 20.0
            # The light comes on with the print and the first frames are badly exposed (lab, 22.11.2026: the only false alarm on an
            # empty plate was the first frame after the light came on): what the AI finds in the first seconds is not judged.
            settle_end = started + 6.0
            early_positive = False
            while reactor.monotonic() < deadline and context['phase'] == 'checking':
                reactor.pause(min(deadline, reactor.monotonic() + 0.8))
                if (sd.current_file is not context['file'] or sd.must_pause_work
                        or context['phase'] != 'checking'):
                    return
                try:
                    frame, foreign = counters()
                except Exception:
                    continue
                if reactor.monotonic() < settle_end:
                    if foreign > initial_foreign and not early_positive:
                        early_positive = True
                        save_frames('early')
                        self.gcode.respond_info('PEI foreign object check: the AI reported an object at %s, in the first seconds after the start; the case light is %s; it is not judged here. The printer screen can show the warning window of the AI for it; this print is NOT paused by it.' % (stamp(time.time()), light()))
                    initial_frame, initial_foreign = frame, foreign   # a new baseline: only what comes later counts
                    continue
                if frame < initial_frame or foreign < initial_foreign:
                    break  # the AI ended its own window and zeroed its counters: nothing was found before that, say so below
                if frame > initial_frame and foreign > initial_foreign:
                    # Reuse the original alarm and its unmodified LCD buttons.
                    save_frames('found')
                    text = 'foreign=1 status=1 time=%d' % time.time()
                    self._foreign_notice(text)
                    context['notice'] = text
                    self.ai_error_type = AIErrorType.FOREIGN
                    self.ai_configs[AIErrorType.FOREIGN]['count'] = 1
                    self.foreign_preflight_command('PAUSE')
                    self.gcode.respond_info('PEI foreign object check: object found on the plate; waiting for Stop/Continue.')
                    return
            self.gcode.respond_info('PEI foreign object check: nothing found.')
        except Exception:
            # Owner-selected stock policy: unavailable AI does not hold a job.
            logging.warning('M4050: AI check unavailable; continuing without popup', exc_info=True)
            self.gcode.respond_info('PEI foreign object check: unavailable; continuing without popup.')
        finally:
            if attempted_start:
                try:
                    requests.post(base + '/set_homing_state', json={'state': False},
                                  timeout=0.2, allow_redirects=False)
                except Exception:
                    logging.warning('M4050: AI stop unconfirmed; no retry', exc_info=True)
            if context['phase'] != 'held' and self._foreign_preflight is context:
                self._foreign_preflight = None

    def _handle_stats_changed(self, old_status, new_status):
        # 当打印完成后清空状态 复位
        if new_status in ['standby', 'error', 'complete', 'cancelled']:
            self.ai_error_type = AIErrorType.NONE
            for key, value in self.ai_configs.items():
                value['count'] = 0
        
    def _handle_stats_changed(self, old_status, new_status):
        # 当打印完成后清空状态 复位
        if new_status in ['standby', 'error', 'complete', 'cancelled']:
            self.ai_error_type = AIErrorType.NONE
            for key, value in self.ai_configs.items():
                value['count'] = 0
            try:
                gone = self._forget_ai_alarm()
                if gone:
                    self.gcode.respond_info('AI alarm "%s" cleared at the end of the print (%s); the window of the screen is closed by pressing a button.' % (gone, time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(time.time()))))
            except Exception:
                logging.warning('AI: could not clear the stored AI alarm', exc_info=True)

